export function CreatorSlider({
  pack,
  layout,
  label,
  value,
  resetKey,
  min,
  max,
  onChange,
  onBegin,
  onEnd,
}: {
  pack: AssetPack;
  layout: CreatorSliderLayout;
  label: string;
  value: number;
  resetKey: object;
  min: number;
  max: number;
  onChange: (value: number) => void;
  onBegin: () => void;
  onEnd: (cancel: boolean) => void;
}) {
  const [current, setCurrent] = useState(value),
    [hover, setHover] = useState(false);
  const dragging = useRef<number | null>(null);
  // Flash recomputes averages on selection changes, while a dragged handle retains its chosen value.
  useLayoutEffect(() => {
    setCurrent(value);
  }, [resetKey]);
  const normalized = Math.max(0, Math.min(1, (current - min) / (max - min))),
    x = -57 + 114 * normalized,
    y = layout.handle.matrix.ty / 20;
  const hitRadius = Math.max(
    ...layout.handle.variants[hover ? 1 : 0].map((p) => (p.bounds.xMax - p.bounds.xMin) / 40),
  );
  const track = pack.creatorFrames.get(`${layout.name}:track`),
    handle = pack.creatorFrames.get(`handle:${hover ? 2 : 1}`);
  const change = (value: number) => {
    setCurrent(value);
    onChange(value);
  };
  const local = (e: React.PointerEvent<HTMLInputElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    return {
      x: ((e.clientX - r.left) * 138) / r.width - 69,
      y: ((e.clientY - r.top) * 28) / r.height - 12,
    };
  };
  const finish = (cancel: boolean) => {
    if (dragging.current === null) return;
    if (cancel) setCurrent(dragging.current);
    dragging.current = null;
    onEnd(cancel);
  };
  return (
    <div
      className="creator-transform-slider"
      data-creator-slider={layout.name}
      style={{ left: layout.matrix.tx / 20, top: layout.matrix.ty / 20 }}
    >
      {track ? (
        <CreatorRasterArt raster={track} />
      ) : (
        <svg
          aria-hidden="true"
          viewBox="-65 -18 130 36"
          width="130"
          height="36"
          style={{ position: 'absolute', left: -65, top: -18, overflow: 'visible' }}
        >
          <CreatorPrimitives pieces={layout.track} />
        </svg>
      )}
      {handle ? (
        <CreatorRasterArt raster={handle} offsetX={x} offsetY={y} />
      ) : (
        <span
          className="creator-mock-handle"
          style={{ left: x - 5, top: y - 5, transform: hover ? 'scale(1.25)' : undefined }}
        />
      )}
      <input
        aria-label={label}
        type="range"
        min={min}
        max={max}
        step="any"
        value={current}
        onChange={(e) => change(Number(e.target.value))}
        onFocus={() => setHover(true)}
        onBlur={() => setHover(false)}
        onPointerMove={(e) => {
          const p = local(e);
          if (dragging.current !== null)
            change(min + ((Math.max(-57, Math.min(57, p.x)) + 57) / 114) * (max - min));
          else setHover(Math.hypot(p.x - x, p.y - y) <= hitRadius);
        }}
        onPointerLeave={() => {
          if (dragging.current === null) setHover(false);
        }}
        onPointerDown={(e) => {
          if (e.button !== 0) return;
          e.preventDefault();
          const p = local(e);
          if (Math.hypot(p.x - x, p.y - y) > hitRadius) return;
          dragging.current = current;
          onBegin();
          e.currentTarget.setPointerCapture(e.pointerId);
          setHover(true);
        }}
        onPointerUp={(event) => {
          if (event.button === 0) finish(false);
        }}
        onPointerCancel={() => finish(true)}
        onLostPointerCapture={() => finish(true)}
      />
    </div>
  );
}
import { StrictMode, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { createPortal } from 'react-dom';
import { CreatorButton, CreatorSlider } from '../../src/components/creator-controls';
import { CREATOR_CONTROLS } from '../../src/game/core/creator-controls';
import type { AssetPack } from '../../src/game/assets/asset-pack';

function ControlsFixture({
  pack,
  host,
  controlsHost,
}: {
  pack: AssetPack;
  host: HTMLElement;
  controlsHost: HTMLElement;
}) {
  const [checked, setChecked] = useState(true),
    [undo, setUndo] = useState(false),
    [scale, setScale] = useState(1),
    [rotation, setRotation] = useState(0),
    [resetKey, setResetKey] = useState({}),
    [x, setX] = useState(0);
  const held = useRef(0),
    before = useRef(1);
  const report = (name: string, value: unknown) => {
    host.dataset[name] = JSON.stringify(value);
  };
  const record = (name: string) => report(name, Number(host.dataset[name] ?? '0') + 1);
  const labels: Record<string, string> = {
    SymmetricMode_mc: 'Symmetric Mode',
    LoadTank_mc: 'Load tank',
    SaveExit_mc: 'Save and exit',
    Exit_mc: 'Exit tank creator',
    DeleteButton_mc: 'Delete selected',
    BringFront_mc: 'Bring to front',
    SendBack_mc: 'Send to back',
    AlignCenter_mc: 'Align to center',
    Undo_mc: 'Undo',
    Left_mc: 'Nudge left',
    Right_mc: 'Nudge right',
  };
  return (
    <>
      <div className="creator stage-background" data-assets={pack.mode}>
        {CREATOR_CONTROLS.controls.map((c) => {
          const direction = c.name === 'Left_mc' ? -1 : c.name === 'Right_mc' ? 1 : 0;
          return (
            <CreatorButton
              key={c.name}
              pack={pack}
              name={c.name}
              label={labels[c.name]}
              checked={c.name === 'SymmetricMode_mc' ? checked : undefined}
              disabled={c.name === 'Undo_mc' && !undo}
              onClick={() => {
                if (c.name === 'SymmetricMode_mc') setChecked((v) => !v);
                if (direction) setX((v) => v + direction);
                record('controlClicks');
              }}
              onHoldStart={
                direction
                  ? () => {
                      held.current = direction;
                      record('holdStarts');
                    }
                  : undefined
              }
              onHoldEnd={
                direction
                  ? (click) => {
                      held.current = 0;
                      if (click) setX((v) => v + direction);
                      record('holdEnds');
                      report('holdClick', click);
                    }
                  : undefined
              }
            />
          );
        })}
        {CREATOR_CONTROLS.sliders.map((layout) => {
          const resize = layout.name === 'Resize_mc';
          return (
            <CreatorSlider
              key={layout.name}
              pack={pack}
              layout={layout}
              label={resize ? 'Part scale' : 'Part rotation'}
              value={resize ? scale : rotation}
              resetKey={resetKey}
              min={resize ? 0.5 : 0}
              max={resize ? 2 : 360}
              onBegin={() => {
                before.current = resize ? scale : rotation;
                record('sliderBegins');
              }}
              onChange={(v) => {
                if (resize) setScale(v);
                else setRotation(v);
                record('sliderChanges');
              }}
              onEnd={(cancel) => {
                if (cancel) {
                  if (resize) setScale(before.current);
                  else setRotation(before.current);
                }
                record('sliderEnds');
                report('sliderCancel', cancel);
              }}
            />
          );
        })}
        <span className="sr-only" data-control-values>
          {JSON.stringify({ checked, scale, rotation, x })}
        </span>
      </div>
      {createPortal(
        <div>
          <button onClick={() => setUndo((v) => !v)}>Toggle fixture undo</button>
          <button
            onClick={() => {
              setScale(3);
              setResetKey({});
            }}
          >
            Load fixture scale 3
          </button>
          <button
            onClick={() => {
              setScale(1);
              setRotation(0);
              setResetKey({});
            }}
          >
            Reset fixture selection
          </button>
          <button onClick={() => setX((v) => v + held.current * 3)}>
            Step fixture hold 3 frames
          </button>
        </div>,
        controlsHost,
      )}
    </>
  );
}
export function showCreatorControls(pack: AssetPack, host: HTMLElement) {
  for (const name of [
    'controlClicks',
    'holdStarts',
    'holdEnds',
    'sliderBegins',
    'sliderChanges',
    'sliderEnds',
  ])
    host.dataset[name] = '0';
  const controlsHost = document.createElement('div');
  controlsHost.id = 'creator-component-fixture-controls';
  host.before(controlsHost);
  const root = createRoot(host);
  root.render(
    <StrictMode>
      <ControlsFixture pack={pack} host={host} controlsHost={controlsHost} />
    </StrictMode>,
  );
  return () => {
    root.unmount();
    controlsHost.remove();
  };
}
